<script setup lang="ts">
import { ref, watch, onUnmounted } from 'vue'
import { getAccessToken } from '@/api/client'
import { resourceApi } from '@/api/modules'
const props=defineProps<{resourceId?:number|null;mediaType?:string;label?:string;autoload?:boolean;poster?:string}>()
const url=ref(''),error=ref(''),loading=ref(false);let marker=0,controller:AbortController|null=null
function release(){controller?.abort();controller=null;if(url.value)URL.revokeObjectURL(url.value);url.value=''}
async function load(){const resourceId=props.resourceId;if(!resourceId||loading.value)return;const request=++marker;release();const activeController=new AbortController();controller=activeController;error.value='';loading.value=true;try{const response=await fetch(resourceApi.fileUrl(resourceId),{headers:{Authorization:`Bearer ${getAccessToken()||''}`},signal:activeController.signal});if(!response.ok)throw new Error('预览加载失败');const blob=URL.createObjectURL(await response.blob());if(request!==marker){URL.revokeObjectURL(blob);return}url.value=blob}catch(event){if(request===marker&&!activeController.signal.aborted)error.value='预览不可用，请检查素材或重试'}finally{if(controller===activeController)controller=null;if(request===marker)loading.value=false}}
watch(()=>[props.resourceId,props.mediaType],()=>{marker++;release();error.value='';loading.value=false;if(props.resourceId&&(props.mediaType!=='video'||props.autoload!==false))void load()},{immediate:true})
onUnmounted(()=>{marker++;release()})
</script>
<template><div class="director-preview"><video v-if="url&&mediaType==='video'" :src="url" controls autoplay playsinline preload="metadata" :aria-label="label||'视频预览'"/><img v-else-if="url" :src="url" :alt="label||'关键帧预览'"/><button v-else-if="resourceId&&mediaType==='video'&&!loading" class="load-video" type="button" @click="load"><img v-if="poster" :src="poster" alt=""/><span><StudioIcon name="play"/></span><b>{{error?'重新加载视频预览':'加载视频预览'}}</b><small>切换镜头时不会自动下载完整视频</small></button><div v-else class="preview-empty"><span><StudioIcon :name="mediaType==='video'?'drama':'creation'"/></span><p>{{ error||(resourceId?'正在加载…':label||'生成或选择候选后在这里预览') }}</p></div></div></template>
<style scoped>.director-preview{display:grid;place-items:center;min-height:240px;aspect-ratio:16/9;background:var(--ws-bg-elevated);border-radius:12px;overflow:hidden}.director-preview img,.director-preview video{width:100%;height:100%;max-height:52vh;object-fit:contain}.preview-empty{text-align:center;color:var(--ws-text-muted)}.preview-empty span{font-size:42px}.preview-empty p{font-size:13px}.load-video{position:relative;width:100%;height:100%;min-height:240px;border:0;background:var(--ws-surface-soft);color:var(--ws-text);display:grid;place-items:center;align-content:center;gap:8px;overflow:hidden;cursor:pointer}.load-video img{position:absolute;inset:0;max-height:none;object-fit:cover;opacity:.42;filter:blur(1px)}.load-video span,.load-video b,.load-video small{position:relative;z-index:1}.load-video span{display:grid;place-items:center;width:58px;height:58px;border-radius:50%;background:#0009;font-size:24px;padding-left:4px}.load-video b{font-size:14px}.load-video small{font-size:11px;color:var(--ws-text)}</style>
